{"summary":"Validate fraud report JSON for required fields and null rules","command":"python3 - <<'PY'
import json
r=json.load(open('/root/fraud_report.json'))
missing=[]
none_amount=[]
invalid_po_field=[]
for rec in r:
    for k in ['invoice_page_number','vendor_name','invoice_amount','iban','po_number','reason']:
        if k not in rec:
            missing.append((rec.get('invoice_page_number'), k))
    if rec.get('invoice_amount') is None:
        none_amount.append(rec['invoice_page_number'])
    if rec.get('reason')=='Invalid PO' and rec.get('po_number') is not None:
        invalid_po_field.append(rec['invoice_page_number'])
print('records', len(r))
print('missing keys', missing[:10])
print('invoice_amount None pages', none_amount)
print('Invalid PO but po_number not null pages', invalid_po_field)
PY","security_risk":"LOW"}

